"use client";

import Script from "next/script";
import { useEffect } from "react";
import { usePathname, useSearchParams } from "next/navigation";

// Pixel ID (from env or fallback)
const PIXEL_ID =
  process.env.NEXT_PUBLIC_FB_PIXEL_ID || "719990012398471004";

export default function FacebookPixel() {
  const pathname = usePathname();
  const searchParams = useSearchParams();

  // Track a PageView whenever the route changes (SPA navigation)
  useEffect(() => {
    if (typeof window === "undefined") return;
    if (typeof window.fbq === "undefined") return;

    window.fbq("track", "PageView");
  }, [pathname, searchParams]);

  return (
    <>
      {/* Base Meta Pixel Code */}
      <Script
        id="fb-pixel-base"
        strategy="afterInteractive"
        dangerouslySetInnerHTML={{
          __html: `
            !function(f,b,e,v,n,t,s)
            {if(f.fbq)return;n=f.fbq=function(){n.callMethod ?
            n.callMethod.apply(n,arguments) : n.queue.push(arguments)};
            if(!f._fbq)f._fbq=n;n.push=n;n.loaded=!0;n.version='2.0';
            n.queue=[];t=b.createElement(e);t.async=!0;
            t.src=v;s=b.getElementsByTagName(e)[0];
            s.parentNode.insertBefore(t,s)}(window, document,'script',
            'https://connect.facebook.net/en_US/fbevents.js');

            // Initialize Pixel
            fbq('init', '${PIXEL_ID}');
            // Initial PageView on first load
            fbq('track', 'PageView');
          `,
        }}
      />

      {/* NoScript fallback for non-JS browsers */}
      <noscript>
        <img
          height="1"
          width="1"
          style={{ display: "none" }}
          src={`https://www.facebook.com/tr?id=${PIXEL_ID}&ev=PageView&noscript=1`}
          alt=""
        />
      </noscript>
    </>
  );
}